    (htarget : 0 < target)
    (hlong : ∀ i ∈ s, target ≤ long i) :
    ((s.filter fun i ↦ short i < target / 2).card : ℝ) ≤
      4 * (∑ i ∈ s, (short i - long i) ^ 2) / target ^ 2

